  # rubocop:enable Layout/LineLength

  # An inline SVG icon one line of text high that takes the text colour.
  def icon(name, class_name: nil)
    width, path = ICONS.fetch(name)
    tag.svg(tag.path(fill: 'currentColor', d: path),
            class: ['icon', "icon-#{name}", class_name].compact.join(' '),
            viewBox: "0 0 #{width} 512",
            width: "#{(width / 512.0).to_s.delete_suffix('.0')}em", height: '1em',
            aria: { hidden: true }, focusable: false, role: 'img',
            xmlns: 'http://www.w3.org/2000/svg')
  end
